#include <bits/stdc++.h>
using namespace std;

struct Node {
    int id;
    long long x, y;
    char type; // R, S, C
};

struct Edge {
    double w;
    int u, v;
    bool operator<(const Edge& o) const { return w < o.w; }
};

int par[3001], rnk[3001];
int find(int x) { return par[x] == x ? x : par[x] = find(par[x]); }
bool unite(int a, int b) {
    a = find(a); b = find(b);
    if (a == b) return false;
    if (rnk[a] < rnk[b]) swap(a, b);
    par[b] = a;
    if (rnk[a] == rnk[b]) rnk[a]++;
    return true;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;

    vector<Node> nodes(N + K);
    map<int, int> idToIdx;

    for (int i = 0; i < N + K; i++) {
        cin >> nodes[i].id >> nodes[i].x >> nodes[i].y >> nodes[i].type;
        idToIdx[nodes[i].id] = i;
    }

    int total = N + K;

    auto edgeCost = [&](int i, int j) -> double {
        char ti = nodes[i].type, tj = nodes[j].type;
        if (ti == 'C' && tj == 'C') return 1e18; // not allowed
        long long dx = nodes[i].x - nodes[j].x, dy = nodes[i].y - nodes[j].y;
        double D = (double)(dx*dx + dy*dy);
        // If either is S and neither is C, factor is 0.8
        if (ti != 'C' && tj != 'C') {
            if (ti == 'S' || tj == 'S') return 0.8 * D;
            return D;
        }
        // One is C, other is R or S: cost is 1.0 * D
        return D;
    };

    // Build edges
    vector<Edge> edges;
    edges.reserve((long long)total * (total - 1) / 2);
    for (int i = 0; i < total; i++)
        for (int j = i + 1; j < total; j++) {
            if (nodes[i].type == 'C' && nodes[j].type == 'C') continue;
            edges.push_back({edgeCost(i, j), i, j});
        }

    sort(edges.begin(), edges.end());

    // Kruskal MST
    for (int i = 0; i < total; i++) { par[i] = i; rnk[i] = 0; }

    vector<Edge> mstEdges;
    // We need all robots connected; relays are optional
    // Run Kruskal, but only require robot connectivity
    int robotComponents = N;
    for (auto& e : edges) {
        if (robotComponents <= 1) {
            // Check if adding this edge helps (connects a useful relay)
            // Actually, after all robots connected, adding relays might not help
            // But we might still want to try replacing edges
        }
        int fu = find(e.u), fv = find(e.v);
        if (fu == fv) continue;
        // Count robot merges
        bool uRobot = (nodes[e.u].type != 'C'), vRobot = (nodes[e.v].type != 'C');
        // We always add if it connects new components
        unite(e.u, e.v);
        mstEdges.push_back(e);
        if (mstEdges.size() == (size_t)(total - 1)) break;
    }

    // Now prune: remove leaf relay stations iteratively
    // Build adjacency
    auto pruneRelays = [&](vector<Edge>& tree) {
        bool changed = true;
        while (changed) {
            changed = false;
            vector<int> deg(total, 0);
            for (auto& e : tree) { deg[e.u]++; deg[e.v]++; }
            vector<Edge> newTree;
            // Find leaf relays
            set<int> toRemove;
            for (int i = 0; i < total; i++) {
                if (nodes[i].type == 'C' && deg[i] <= 1) {
                    toRemove.insert(i);
                    changed = true;
                }
            }
            for (auto& e : tree) {
                if (toRemove.count(e.u) || toRemove.count(e.v)) continue;
                newTree.push_back(e);
            }
            tree = newTree;
        }
    };

    pruneRelays(mstEdges);

    // Collect used relays
    set<int> usedRelays;
    for (auto& e : mstEdges) {
        if (nodes[e.u].type == 'C') usedRelays.insert(e.u);
        if (nodes[e.v].type == 'C') usedRelays.insert(e.v);
    }

    // Now try improvement: for each relay with degree 2 in the tree, check if removing it
    // and connecting its two neighbors directly is cheaper
    // Build adjacency list
    auto tryImprove = [&](vector<Edge>& tree) {
        bool changed = true;
        while (changed) {
            changed = false;
            vector<vector<pair<int,int>>> adj(total);
            for (int i = 0; i < (int)tree.size(); i++) {
                adj[tree[i].u].push_back({tree[i].v, i});
                adj[tree[i].v].push_back({tree[i].u, i});
            }
            for (int c = 0; c < total; c++) {
                if (nodes[c].type != 'C') continue;
                if (adj[c].size() == 2) {
                    int a = adj[c][0].first, b = adj[c][1].first;
                    int ei = adj[c][0].second, ej = adj[c][1].second;
                    double oldCost = tree[ei].w + tree[ej].w;
                    double newCost = edgeCost(a, b);
                    if (newCost <= oldCost + 1e-9) {
                        // Replace
                        set<int> rem = {ei, ej};
                        vector<Edge> nt;
                        for (int i = 0; i < (int)tree.size(); i++)
                            if (!rem.count(i)) nt.push_back(tree[i]);
                        nt.push_back({newCost, a, b});
                        tree = nt;
                        pruneRelays(tree);
                        changed = true;
                        break;
                    }
                }
            }
        }
    };

    tryImprove(mstEdges);

    // Output
    usedRelays.clear();
    for (auto& e : mstEdges) {
        if (nodes[e.u].type == 'C') usedRelays.insert(e.u);
        if (nodes[e.v].type == 'C') usedRelays.insert(e.v);
    }

    if (usedRelays.empty()) cout << "#" << "\n";
    else {
        bool first = true;
        for (int c : usedRelays) {
            if (!first) cout << "#";
            cout << nodes[c].id;
            first = false;
        }
        cout << "\n";
    }

    bool first = true;
    for (auto& e : mstEdges) {
        if (!first) cout << "#";
        cout << nodes[e.u].id << "-" << nodes[e.v].id;
        first = false;
    }
    cout << "\n";

    return 0;
}
